import { buscarZonaRepository, buscarJardineroRepository, asignarJardineroRepository } from './repository.mjs';

export class ReferenciaInexistenteError extends Error {}

export async function asignarJardineroService(zonaId, jardineroId, rol) {
  const zona = await buscarZonaRepository(zonaId);
  const jardinero = await buscarJardineroRepository(jardineroId);
  if (!zona || !jardinero) {
    throw new ReferenciaInexistenteError('No existe la zona o el jardinero');
  }
  return asignarJardineroRepository(zonaId, jardineroId, rol);
}

import { asignarJardineroService, ReferenciaInexistenteError } from './service.mjs';

export async function handler(event) {
  const zonaId = Number(event.pathParameters.zonaId);
  const { jardineroId, rol } = JSON.parse(event.body);
  try {
    const asignacion = await asignarJardineroService(zonaId, jardineroId, rol);
    return { statusCode: 201, body: JSON.stringify(asignacion) };
  } catch (error) {
    if (error instanceof ReferenciaInexistenteError) {
      return { statusCode: 404, body: JSON.stringify({ message: error.message }) };
    }
    if (error.name === 'ConditionalCheckFailedException') {
      return { statusCode: 409, body: JSON.stringify({ message: 'El jardinero ya está asignado a esa zona' }) };
    }
    throw error;
  }
}

